// 1. Fetch extractor payload
const extractorNode = $('Information Extractor').first()?.json || {};
const extractorData = extractorNode.output || extractorNode;

// 2. Fetch the existing booking record from Supabase
const existingBooking = $('Find Booking to Reschedule').first()?.json || {};
const patient = existingBooking.patients || {};
const doctor = existingBooking.doctors || {};

// 3. Fetch Clinic Configuration
const config = $('Clinic Config').first()?.json || {};
const tz = config.timezone || 'Asia/Kolkata';
const openHour = config.opening_hour !== undefined ? Number(config.opening_hour) : 9;
const closeHour = config.closing_hour !== undefined ? Number(config.closing_hour) : 18;
const defaultDuration = config.slot_duration_mins !== undefined ? Number(config.slot_duration_mins) : 30;
const workingDays = Array.isArray(config.working_days) ? config.working_days : [1, 2, 3, 4, 5, 6];

// 4. Target reschedule slot requested by the patient
const rawStart = extractorData.requested_new_appointment_start
  || extractorData.reschedule_start
  || extractorData.new_appointment_time
  || extractorData.appointment_start;

if (!rawStart) {
  const eventId = existingBooking.calendar_event_id 
    || existingBooking.google_event_id 
    || existingBooking.event_id;

  return [
    {
      json: {
        existing_event_id: eventId,
        booking_id: existingBooking.id,
        patient_id: existingBooking.patient_id,
        patient_name: patient.patient_name || existingBooking.patient_name || 'Rahul Rampuria',
        patient_phone: patient.patient_phone || existingBooking.patient_phone || '+919830127501',
        telegram_chat_id: patient.telegram_chat_id,
        doctor_id: existingBooking.doctor_id,
        doctor_name: doctor.name || existingBooking.doctor_name || 'Dr. Mark',
        calendar_id: doctor.calendar_id,
        slot_start: null,
        slot_end: null,
        is_valid_slot: false,
        rejection_reason: 'No target reschedule date or time specified by caller.'
      }
    }
  ];
}

// 5. Parse dates using Luxon with clinic timezone
const startDateTime = DateTime.fromISO(rawStart).setZone(tz);
const rawEnd = extractorData.requested_new_appointment_end
  || extractorData.reschedule_end
  || extractorData.appointment_end;

const endDateTime = rawEnd 
  ? DateTime.fromISO(rawEnd).setZone(tz)
  : startDateTime.plus({ minutes: defaultDuration });

// 6. Validate clinic operating constraints
const now = DateTime.now().setZone(tz);
const isPast = startDateTime < now;
const isWorkingDay = workingDays.includes(startDateTime.weekday);
const isWithinHours = startDateTime.hour >= openHour && startDateTime.hour < closeHour;
const isMidnightDefault = startDateTime.hour === 0 && startDateTime.minute === 0;

let isValidSlot = true;
let rejectionReason = null;

if (isPast) {
  isValidSlot = false;
  rejectionReason = 'Requested slot is in the past.';
} else if (!isWorkingDay) {
  isValidSlot = false;
  rejectionReason = 'Clinic is closed on Sundays / non-working days.';
} else if (isMidnightDefault) {
  isValidSlot = false;
  rejectionReason = 'Caller mentioned a date but did not specify an appointment time.';
} else if (!isWithinHours) {
  isValidSlot = false;
  rejectionReason = `Requested time (${startDateTime.toFormat('hh:mm a')}) is outside operating hours (${openHour}:00 AM - ${closeHour}:00 PM).`;
}

// 7. Resolve calendar event ID and identifiers
const eventId = existingBooking.calendar_event_id 
  || existingBooking.google_event_id 
  || existingBooking.event_id;

return [
  {
    json: {
      existing_event_id: eventId,
      booking_id: existingBooking.id,
      patient_id: existingBooking.patient_id,
      patient_name: patient.patient_name || existingBooking.patient_name || 'Rahul Rampuria',
      patient_phone: patient.patient_phone || existingBooking.patient_phone || '+919830127501',
      telegram_chat_id: patient.telegram_chat_id,
      doctor_id: existingBooking.doctor_id,
      doctor_name: doctor.name || existingBooking.doctor_name || 'Dr. Mark',
      calendar_id: doctor.calendar_id,
      slot_start: startDateTime.toISO(),
      slot_end: endDateTime.toISO(),
      is_valid_slot: isValidSlot,
      rejection_reason: rejectionReason
    }
  }
];

