let patientName = 'Valued Patient';
let patientPhone = 'Unknown Phone';
let callId = null;
let requestedDate = 'N/A';

try {
  const vapiData = $('Vapi Post-Call Ingest').first().json || {};
  const extractorNode = $('Information Extractor').first()?.json || {};
  const extracted = extractorNode.output || extractorNode;

  // 1. Structured patient name with multi-level fallback
  if (extracted.patient_name && String(extracted.patient_name).trim() !== '') {
    patientName = String(extracted.patient_name).trim();
  } else if (vapiData.message?.customer?.name) {
    patientName = vapiData.message.customer.name;
  }

  // 2. Patient phone with full defensive chaining
  patientPhone = extracted.patient_phone 
              || extracted.caller_phone 
              || extracted.phone 
              || vapiData.message?.call?.customer?.number 
              || vapiData.message?.customer?.number 
              || vapiData.customer?.number 
              || patientPhone;

  // 3. Call ID & appointment start reference if available
  callId = vapiData.message?.call?.id || vapiData.message?.callId || null;
  if (extracted.appointment_start) {
    requestedDate = extracted.appointment_start;
  }
} catch (error) {
  // Safe defaults persist if node context is unlinked during partial manual test runs
}

return [{
  json: {
    patient_name: patientName,
    patient_phone: patientPhone,
    requested_date: requestedDate,
    reason: 'Active booking not found in database',
    call_id: callId
  }
}];

