const items = $input.all();
if (!items.length) return [];

const item = items[0].json;
const raw = item.body || item;

// 1. Keep your thorough transcript fallbacks
let transcript = 
  raw.message?.transcript ||
  raw.message?.artifact?.transcript ||
  raw.transcript ||
  raw.artifact?.transcript ||
  raw.message?.call?.transcript ||
  raw.chatInput ||
  raw.text ||
  '';

if (typeof transcript !== 'string') {
  transcript = '';
}
transcript = transcript.trim();

// 2. Keep your phone number fallbacks
let incomingPhone = 
  raw.message?.customer?.number ||
  raw.message?.call?.customer?.number ||
  raw.customer?.number ||
  raw.call?.customer?.number ||
  raw.patient_phone ||
  raw.phone ||
  null;

// Clean & normalize phone number
let normalizedPhone = null;
let last10Digits = null;

if (incomingPhone) {
  const digitsOnly = String(incomingPhone).replace(/\D/g, '');
  if (digitsOnly.length >= 10) {
    last10Digits = digitsOnly.slice(-10);
    normalizedPhone = `+91${last10Digits}`;
  } else if (digitsOnly.length > 0) {
    last10Digits = digitsOnly;
    normalizedPhone = `+${digitsOnly}`;
  }
}

// 3. Extract duration and hangup reason
const durationSeconds = 
  raw.message?.durationSeconds ||
  raw.message?.call?.duration ||
  raw.durationSeconds ||
  raw.duration ||
  0;

const endedReason = 
  raw.message?.endedReason ||
  raw.message?.call?.endedReason ||
  raw.endedReason ||
  '';

// 4. Edge-case validation checks
const isTooShort = transcript.length < 15;
const isPrematureDrop = durationSeconds > 0 && durationSeconds < 5;
const isGhostOrSilence = ['silence-timed-out', 'customer-did-not-answer'].includes(endedReason);

const isValidCall = !isTooShort && !isPrematureDrop && !isGhostOrSilence;

return [{
  json: {
    transcript: transcript,
    patient_phone: normalizedPhone,
    phone_last_10: last10Digits,
    duration_seconds: durationSeconds,
    ended_reason: endedReason,
    is_valid_call: isValidCall,
    drop_reason: !isValidCall 
      ? `Ignored: Transcript too short (${transcript.length} chars), duration (${durationSeconds}s), or silent drop (${endedReason || 'n/a'}).`
      : null
  }
}];

