const calendarEvents = $('Check New Slot Availability').all();
const targetData = $('Prepare Slot Dates').first()?.json || {};
const existingEventId = targetData.existing_event_id;

// Check if any returned item has an ID that does NOT match the existing appointment
const conflictingEvents = calendarEvents.filter(item => {
  const id = item.json?.id;
  return id && id !== existingEventId;
});

const isFree = conflictingEvents.length === 0;

return [{
  json: {
    ...targetData,
    is_slot_free: isFree,
    status_text: isFree ? "free" : "conflict"
  }
}];

